(42, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(43, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(44, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(45, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(46, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(47, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(48, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(49, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(50, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(51, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(52, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(53, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(54, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(55, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(56, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(57, 'woocommerce-analytics-order-attribution-promotions-december-2024', 'marketing', 'en_US', 'Discover what drives your sales', 'Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(58, 'stripe_stripetax_q1_2025', 'marketing', 'en_US', 'Say goodbye to your tax woes', 'Stripe Tax automatically applies the correct sales tax, VAT, or GST, saving time while keeping you compliant. And with simple automatic filing, you can stop stressing at tax time and focus on growing instead.', '{}', 'pending', 'woocommerce.com', '2025-02-20 14:08:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(59, 'wc-admin-choosing-a-theme', 'marketing', 'en_US', 'Выбираете тему?', 'Узнайте, какие темы совместимы с WooCommerce и выберите ту, что лучше подойдёт под стиль и требования вашего бизнеса.', '{}', 'unactioned', 'woocommerce-admin', '2025-02-25 18:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(60, 'wc-admin-mobile-app', 'info', 'en_US', 'Установите мобильное приложение Woo', 'Установите мобильное приложение WooCommerce для управления заказами, получения уведомлений о продажах и просмотра ключевых показателей — где бы вы ни находились.', '{}', 'unactioned', 'woocommerce-admin', '2025-02-25 18:23:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(61, 'wc-admin-onboarding-payments-reminder', 'info', 'en_US', 'Начните принимать платежи в своем магазине!', 'Принимайте платежи в удобной для вас системе — вам доступны более 100 платежных шлюзов для WooCommerce.', '{}', 'unactioned', 'woocommerce-admin', '2025-02-25 18:23:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(62, 'printful_promo_q1_2025', 'marketing', 'en_US', 'New: sell print-on-demand products, risk-free', 'Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.', '{}', 'pending', 'woocommerce.com', '2025-02-27 14:25:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(63, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2025-03-11 17:33:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(64, 'woo-marketplace-two-year-subscriptions-rin-2025-03-17', 'marketing', 'en_US', 'Save 20% on new two-year subscriptions', 'We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.', '{}', 'pending', 'woocommerce.com', '2025-03-16 22:03:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(65, 'stripe_orderstatus_bug_q2_2025', 'update', 'en_US', 'Action Required: Update Order Status Manager', 'Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.', '{}', 'pending', 'woocommerce.com', '2025-04-12 11:41:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(66, 'wc-admin-real-time-order-alerts', 'info', 'en_US', 'Получайте уведомления о новых заказах в реальном времени, где бы вы ни находились', 'Получайте уведомления об активности в магазине, в том числе о размещении новых заказов и отзывов о товарах, прямо на мобильные устройства благодаря приложению Woo.', '{}', 'unactioned', 'woocommerce-admin', '2025-05-23 13:29:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(67, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2025-05-23 13:30:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(68, 'payson-retirement-2025', 'update', 'en_US', 'Payson Form Retirement', 'Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.', '{}', 'pending', 'woocommerce.com', '2025-05-23 13:30:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(69, 'paypal_q2_2025', 'marketing', 'en_US', 'Power up sales with Pay Later messaging', 'Help increase your sales and grow cart sizes by letting customers know they have flexible payment options. Merchants see up to an 11% sales lift when they add Pay Later messaging — plus, it integrates seamlessly with your PayPal checkout.', '{}', 'pending', 'woocommerce.com', '2025-05-23 13:30:01', NULL, 0, 'plain', '', 0, 0, 'info'),
(70, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2025-06-26 09:33:13', NULL, 0, 'plain', '', 0, 0, 'info'),
(71, 'woopayments-multibanco-alipay-wechat-launch-2025-06-23', 'marketing', 'en_US', 'Multibanco, AliPay and WeChat now available in WooPayments', 'Multibanco, AliPay, and WeChat Pay are now available in WooPayments! Offer trusted local payment methods to customers in key global markets and boost international sales. Geo restrictions apply.', '{}', 'pending', 'woocommerce.com', '2025-06-26 09:33:13', NULL, 0, 'plain', '', 0, 0, 'info'),
(72, 'woopayments-grabpay-launch-2025-07-07', 'marketing', 'en_US', 'GrabPay now available in WooPayments', 'Offer GrabPay through WooPayments and make checkout easier for customers across Southeast Asia. Enable it today and expand your reach with a payment method they know and trust.', '{}', 'pending', 'woocommerce.com', '2025-07-10 13:37:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(73, 'wc-admin-launch-checklist', 'info', 'en_US', 'Готовы запустить собственный магазин?', 'Чтобы у вас не возникало чувство, что вы что-то забыли, мы составили контрольный список для проверки настроек перед запуском.', '{}', 'unactioned', 'woocommerce-admin', '2025-07-27 09:45:20', NULL, 0, 'plain', '', 0, 0, 'info'),
(74, 'woohoo10-coupon', 'marketing', 'en_US', 'Celebrate and save with WooCommerce 10.0', 'To mark this milestone release, get 10% off extensions and themes in the official Woo Marketplace. Use code WOOHOO10 at checkout to save on essential tools that help grow your business. Offer ends August 15, 2025. Terms and conditions apply.', '{}', 'unactioned', 'woocommerce.com', '2025-07-27 09:45:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(75, 'paypaladvantage_q3_2025', 'marketing', 'en_US', 'Add PayPal Checkout and earn up to $1,000*', 'PayPal Checkout can boost conversion by up to 46% and average order value by up to 62% with no disruption to your checkout. New US merchants who activate by August 31 save 25% on transaction fees for 6 months. Excludes Venmo. Terms apply.*', '{}', 'pending', 'woocommerce.com', '2025-07-27 09:45:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(76, 'stripe_optimizedcheckout_upgrade_q3_2025', 'marketing', 'en_US', 'Upgrade for a faster, more flexible Stripe checkout', 'You\'re not on the latest WooCommerce Stripe Payment Gateway version. Upgrade to version 9.8 to access Stripe\'s Optimized Checkout Suite and leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-13 20:32:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(77, 'stripe_optimizedcheckout_enable_q3_2025', 'marketing', 'en_US', 'Unlock dynamic payments and sell more', 'You’re on the latest WooCommerce Stripe Payment Gateway — now unlock its full potential by enabling the Optimized Checkout Suite. It uses AI models to dynamically surface the most relevant payment methods for each customer, helping you boost conversions.', '{}', 'pending', 'woocommerce.com', '2025-08-13 20:32:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(78, 'stripe_optimizedcheckout_promotion_q3_2025', 'marketing', 'en_US', 'Upgrade to Stripe for a faster, more flexible checkout', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-16 05:17:48', NULL, 0, 'plain', '', 0, 0, 'info'),
(79, 'wc-admin-manage-orders-on-the-go', 'info', 'en_US', 'Управляйте заказами на ходу', 'Просматривайте заказы и данные клиента, обрабатывайте возвраты одним нажатием в приложении Woo.', '{}', 'unactioned', 'woocommerce-admin', '2025-08-20 04:04:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(80, 'woo-subscription-gifting-bundling-2025-08-18', 'marketing', 'en_US', 'Grow recurring revenue with gifting', 'WooCommerce Subscriptions now includes gifting. Customers can buy subscriptions for others, helping you reach new shoppers and grow recurring revenue with less effort. Update to the latest version of Subscriptions (7.8.0) to start offering gifting.', '{}', 'pending', 'woocommerce.com', '2025-08-20 04:04:14', NULL, 0, 'plain', '', 0, 0, 'info'),
(81, 'stripe_optimizedcheckout_competitors_q3_2025', 'marketing', 'en_US', 'Upgrade to the official WooCommerce Stripe Payment Gateway', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Use AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click checkout with Link.', '{}', 'pending', 'woocommerce.com', '2025-08-29 05:50:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(82, 'UPS-promo-RIN-WCS-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-10 21:36:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(83, 'UPS-promo-RIN-WCST-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-10 21:36:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(84, 'square_ordersync_upgrade_q3_2025', 'marketing', 'en_US', 'You asked, we delivered — order sync is here for Square', 'Update your Square extension to v5.0 to access <a href=\"https://woocommerce.com/document/woocommerce-square/sync-settings/sync-orders-between-woocommerce-and-square/\">automatic order syncing</a>. Manage your online sales in Square, keep reports accurate, and save time with order updates visible across both platforms.', '{}', 'pending', 'woocommerce.com', '2025-09-11 14:20:11', NULL, 0, 'plain', '', 0, 0, 'info'),
(85, 'woopayments-new-lpms-2025-06-30', 'marketing', 'en_US', 'Get the POS built specifically for Woo stores', 'Introducing WooCommerce POS, our new point-of-sale solution built to get you up and running quickly with in-person sales. Search products, scan barcodes, apply coupons, and send email receipts — right in the WooCommerce mobile app, with all of your online and physical sales synced in real time — no extra setup required', '{}', 'pending', 'woocommerce.com', '2025-09-15 19:54:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(86, 'klaviyo_q3_2025', 'marketing', 'en_US', 'Smarter marketing starts with Woo x Klaviyo', 'Personalize every customer interaction with Klaviyo, Woo\'s preferred marketing automation solution. Advanced segmentation based on real customer behavior lets you create email and SMS campaigns focused on driving loyalty and revenue. So you can grow sales while simplifying your stack.', '{}', 'pending', 'woocommerce.com', '2025-09-17 11:29:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(87, 'pinterest_q3_20252', 'marketing', 'en_US', 'More visibility, smarter campaigns', 'Connect your store to Pinterest via the Conversions API, a new feature in the latest version of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Get started today — connect and sync your catalog using the Conversions API.', '{}', 'pending', 'woocommerce.com', '2025-09-24 14:35:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(88, 'pinterest_q4_2025', 'marketing', 'en_US', 'Maximize conversions with Pinterest', 'Connect your store to Pinterest via the Conversions API, now part of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Sync your catalog and create your first ad today.', '{}', 'pending', 'woocommerce.com', '2025-10-22 14:42:59', NULL, 0, 'plain', '', 0, 0, 'info'),
(89, 'wc-admin-new-sales-record', 'info', 'en_US', 'Новый рекорд продаж!', 'Ого, 22.10.2025 был вашим рекордным днём по продажам! Чистая выручка 14550,00 ₽ побила предыдущий рекорд 225,00 ₽ установленный 27.07.2025.', '{\"old_record_date\":\"2025-07-27\",\"old_record_amt\":225,\"new_record_date\":\"2025-10-22\",\"new_record_amt\":14550}', 'unactioned', 'woocommerce-admin', '2025-10-23 14:44:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(90, 'paypaladvantage_q4_2025', 'marketing', 'en_US', 'PayPal Checkout offer: Get 40% back on fees for 3 months', 'Download and activate PayPal Payments in your WooCommerce admin, then complete your first transaction by 15 December 2025 to get 40% back on PayPal transaction fees — up to £2,000 for 3 months. PayPal Checkout works with your existing checkout. See terms: paypal.com/uk/campaign/paypalmerchantpromotion/terms.', '{}', 'pending', 'woocommerce.com', '2025-11-05 14:31:40', NULL, 0, 'plain', '', 0, 0, 'info'),
(91, 'wc-admin-orders-milestone', 'info', 'en_US', 'Получен первый заказ', 'Поздравляем с получением первого заказа! Самое время узнать, как управлять этими заказами.', '{\"current_milestone\":1}', 'unactioned', 'woocommerce-admin', '2025-11-10 13:56:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(92, 'reddit_q4_2025', 'marketing', 'en_US', 'New: Reach high-intent shoppers on Reddit', 'Sync your catalog and pixel with Reddit for WooCommerce. Launch your ads faster on Reddit and connect with their 400M+ weekly active users and shoppers who turn to this platform for authentic conversations and recommendations.', '{}', 'pending', 'woocommerce.com', '2025-11-14 14:38:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(93, 'wc-admin-performance-on-mobile', 'info', 'en_US', 'Отслеживайте показатели магазина на мобильном устройстве', 'Следите за продажами и показателями лучших товаров с помощью приложения Woo.', '{}', 'unactioned', 'woocommerce-admin', '2025-11-17 14:20:14', NULL, 0, 'plain', '', 0, 0, 'info'),
(94, 'bfcm_general_sale_q4_2025', 'marketing', 'en_US', 'Save up to 40% on extensions and themes', 'For a limited time, take up to 40% off nearly everything in our Marketplace. It’s the perfect moment to give your store a holiday boost and level up for 2026. Sale ends December 2, 2025, at 14:00 UTC.', '{}', 'pending', 'woocommerce.com', '2025-11-20 14:12:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(95, 'paypal-carding-recaptcha-dec-25', 'update', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'pending', 'woocommerce.com', '2025-12-04 14:07:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(96, 'Googleupdate_q4_2025', 'marketing', 'en_US', 'Make every ad dollar count this holiday season', 'Google for WooCommerce now includes Budget Recommendations. Install the latest version and get personalized suggestions on where to optimize campaign budgets to reach more holiday shoppers this season.', '{}', 'pending', 'woocommerce.com', '2025-12-05 14:07:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(97, 'holiday_shipping_deadlines_WCST_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 14:08:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(98, 'holiday_shipping_deadlines_WCS_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 14:08:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(99, 'snap_q4_2025', 'marketing', 'en_US', 'New: Reach a new audience on Snapchat', '88% of Snapchatters love to shop, and 40% aren\'t active on other social platforms. Connect with them and grow your business using Snapchat for WooCommerce, our new official extension. Sync your products, launch ad campaigns, and track results — all from your Woo dashboard.', '{}', 'pending', 'woocommerce.com', '2025-12-19 14:07:51', NULL, 0, 'plain', '', 0, 0, 'info'),
(100, 'stripe_agenticcommerce_3PDS_q4_2025', 'marketing', 'en_US', 'Get more from Stripe with the official extension', 'Switch to the official extension co-developed with Stripe for the latest features and best performance. Get access to personalized checkout options, early support for AI shopping through Stripe’s <a href=\"https://woocommerce.com/posts/stripe-agentic-commerce-suite-for-woocommerce/\">Agentic Commerce Suite</a>, and more.', '{}', 'pending', 'woocommerce.com', '2025-12-19 14:07:51', NULL, 0, 'plain', '', 0, 0, 'info'),
(101, 'WC10.4.3-security-update-12-22-2025', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Please update to WooCommerce 10.4.3 to resolve a security issue.</strong> This update addresses an issue with the WooCommerce Store API that may have made guest order information visible to other logged in users. See the <a href=\"https://developer.woocommerce.com/2025/12/22/store-api-vulnerability-patched-in-woocommerce-8-1/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-12-23 14:07:58', NULL, 0, 'plain', '', 0, 0, 'info'),
(102, 'paypal-carding-recaptcha-jan-26', 'update', 'en_US', 'Fraud protection is now required — enable today', 'Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.', '{}', 'pending', 'woocommerce.com', '2026-01-16 15:57:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(103, 'existing_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2026-01-25 23:05:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(104, 'prospects_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.', '{}', 'pending', 'woocommerce.com', '2026-01-25 23:05:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(105, 'Googleupdate_q1_2026', 'marketing', 'en_US', 'Make every ad dollar count', 'Google for WooCommerce now includes Budget Recommendations. Promote your products across Google — from Search to YouTube and beyond — and get personalized suggestions on where to optimize campaign budgets to reach more shoppers.', '{}', 'pending', 'woocommerce.com', '2026-02-14 18:36:49', NULL, 0, 'plain', '', 0, 0, 'info');
